<?php
$active=(int)$pdo->query(history_sql('SELECT COUNT(*) FROM products WHERE active=1'))->fetchColumn();$sell=$ns=$in=$low=$out=$neg=0;
foreach($products as $p){$s=stock_row($p['id']);$sell+=$s['current'];$ns+=$s['nonsellable'];$status=stock_status_key(detect_status($s['current'],$p['low_stock_threshold']??10)[0]);if($status==='in')$in++;elseif($status==='low')$low++;elseif($status==='out')$out++;elseif($status==='negative')$neg++;}
$unmapped=(int)$pdo->query(history_sql("SELECT COUNT(DISTINCT CONCAT(platform,'|',normalized_item)) FROM unmapped_imports WHERE status='Pending'"))->fetchColumn();
echo '<div class="page-head"><div><h1>Dashboard</h1><p>Check inventory, choose your task, and review pending work.</p></div></div>';usability_quick_tasks();
$groups=['Inventory Overview'=>[['Active Products',$active,'products'],['Sellable Units',$sell,'stocks'],['In Stock',$in,'stocks&status=in'],['Non-Sellable Units',$ns,'nonsellable']],'Stock Alerts & Exceptions'=>[['Negative Stock',$neg,'stocks&status=negative'],['Low Stock',$low,'stocks&status=low'],['Out of Stock',$out,'stocks&status=out'],['Unmapped Items',$unmapped,'mapping']]];
echo '<div class="ux-dashboard-groups">';foreach($groups as $title=>$cards){echo '<section><h3>'.e($title).'</h3><div class="ux-dashboard-cards">';foreach($cards as [$label,$value,$url])echo '<a class="ux-metric '.($title==='Stock Alerts & Exceptions'&&$value>0?'has-pending':'').'" href="?page='.e($url).'"><span>'.ui_icon($label).e($label).'</span><strong>'.number_format($value).'</strong><small>View details ↗</small></a>';echo '</div></section>';}echo '</div>';
usability_terms();
echo '<div class="ux-dashboard-secondary"><section class="card ux-platform-alerts"><div class="card-head"><h3>Platform Stock Alerts</h3><a href="?page=platform_inventory">View all alerts</a></div><p class="muted small">Product counts by platform and stock status.</p><div class="ux-platform-cards">';
foreach(['Lazada','Shopee','TikTok'] as $pl){$q=$pdo->prepare(history_sql('SELECT p.id,COALESCE(ps.qty,0) qty,COALESCE(p.low_stock_threshold,10) threshold FROM products p LEFT JOIN platform_stock ps ON ps.product_id=p.id AND ps.platform=? WHERE p.active=1'));$q->execute([$pl]);$counts=['low'=>0,'out'=>0,'negative'=>0];foreach($q as $r){$key=stock_status_key(detect_status((int)$r['qty'],(int)$r['threshold'])[0]);if(isset($counts[$key]))$counts[$key]++;}echo '<div class="ux-platform-card">'.platform_label($pl).'<div class="ux-platform-counts">';foreach(['low'=>'Low Stock','out'=>'Out of Stock','negative'=>'Negative Stock'] as $key=>$label)echo '<a class="'.($counts[$key]>0?'has-pending':'').'" aria-label="'.e($pl.' '.$label.': '.$counts[$key].' products').'" href="?page=platform_inventory&platform='.$pl.'&status='.$key.'"><strong>'.$counts[$key].'</strong><span>'.$label.'</span></a>';echo '</div></div>';}
echo '</div></section><section class="card ux-control-status"><h3>Control Status</h3><div class="control-list"><div><span>Beginning Balance</span>'.badge(setting('beginning_locked','0')==='1'?'Locked':'Open','neutral').'</div><div><span>Negative stock items</span><b>'.$neg.'</b></div></div><a class="btn '.($neg>0?'primary':'ghost').'" href="?page=reconciliation">Open Reconciliation</a></section></div>';
usability_attention();usability_activity();
